prts.feedbackvariables:
/* funcs is *list* */
funcs:[ans1,ans2];
yys:[y[1],y[2]];
odes:[ode1,ode2];
yy0:[y10,y20];
yy1:[y11,y21];
n:2;
isSol(funcs):= block(sa1:subst(makelist(yys[i]=funcs[i],i,1,n),odes),sa2:ev(sa1,nouns),sa3:trigsimp(fullratsimp(expand(radcan(sa2)))), is(sa3[1])and is(sa3[2]));
isSTIC(funcs):= is(equal(subst(x=x0,funcs),yy0)) and is(equal(subst(x=x0,diff(funcs,x)),yy1));
